WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, key, attr_value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) li AS key, attr_value) SELECT customer_id, COUNT(*) AS event_count, COUNT(*) AS num_rows, COUNT_IF(key = 'utm_source') AS utm_source_events, COUNT(DISTINCT key) AS distinct_keys, COUNT(*) FILTER (WHERE key = 'weight_kg') AS weight_kg_rows, MIN(created_at) AS first_seen FROM exploded GROUP BY customer_id ORDER BY num_rows DESC;
